public: ListNode* deleteMiddle(ListNode* head) { if(head == NULL || head->next == NULL){ return NULL; } ListNode* dummyHead = new ListNode(0); dummyHead->next = head; ListNode* slow = dummyHead; ListNode* fast = head; while(fast != NULL && fast->next != NULL){ fast = fast->next->next; slow = slow->next; } slow->next = slow->next->next; return dummyHead->next; }
}; 普通解法： /** * Definition for singly-linked list. * struct ListNode { * int val; * ListNode *next; * ListNode() : val(0), next(nullptr) {} * ListNode(int x) : val(x), next(nullptr) {} * ListNode(int x, ListNode *next) : val(x), next(next) {} * }; */
class Solution {
public: ListNode* deleteMiddle(ListNode* head) { int length = 0; ListNode* pMove = head; while(pMove){ length += 1; pMove = pMove->next; } if(length <= 1){ return NULL; } int index = length % 2 == 1 ? (length - 1) / 2 : length / 2; ListNode* pre = NULL; ListNode* cur = head; for(; index > 0; index--){ pre = cur; cur = cur->next; } if(pre->next){ pre->next = cur->next; } return head; }
};

