Approach 3: Reverse Twice class Solution {
private: ListNode* reverseList(ListNode* head) { ListNode* prev = nullptr; ListNode* current = head; ListNode* nextTemp = nullptr; // Set each node's next pointer to the previous node while (current != nullptr) { nextTemp = current->next; current->next = prev; prev = current; current = nextTemp; } return prev; }
public: ListNode* removeNodes(ListNode* head) { // Reverse the original linked list head = reverseList(head); int maximum = 0; ListNode* prev = nullptr; ListNode* current = head; // Traverse the list deleting nodes while (current != nullptr) { maximum = max(maximum, current->val); // Delete nodes that are smaller than maximum if (current->val < maximum) { // Delete current by skipping prev->next = current->next; ListNode* deleted = current; current = current->next; deleted->next = nullptr; } // Current does not need to be deleted else { prev = current; current = current->next; } } // Reverse and return the modified linked list return reverseList(head); }
}; Approach 2: Recursion /** * Definition for singly-linked list. * struct ListNode { * int val; * ListNode *next; * ListNode() : val(0), next(nullptr) {} * ListNode(int x) : val(x), next(nullptr) {} * ListNode(int x, ListNode *next) : val(x), next(next) {} * }; */
class Solution {
public: ListNode* removeNodes(ListNode* head) { // Base case, reached end of the list if (head == nullptr || head->next == nullptr) { return head; } // Recursive call ListNode* nextNode = removeNodes(head->next); // If the next node has greater value than head delete the head // Return next node, which removes the current head and makes next the new head if (head->val < nextNode->val) { return nextNode; } // Keep the head head->next = nextNode; return head; }
}; Approach 1: Stack /** * Definition for singly-linked list. * struct ListNode { * int val; * ListNode *next; * ListNode() : val(0), next(nullptr) {} * ListNode(int x) : val(x), next(nullptr) {} * ListNode(int x, ListNode *next) : val(x), next(next) {} * }; */
class Solution {
public: ListNode* removeNodes(ListNode* head) { stack<ListNode*> stack; ListNode* current = head; // Add nodes to the stack while (current != nullptr) { stack.push(current); current = current->next; } current = stack.top(); stack.pop(); int maximum = current->val; ListNode* resultList = new ListNode(maximum); // Remove nodes from the stack and add to result while (!stack.empty()) { current = stack.top(); stack.pop(); // Current should not be added to the result if (current->val < maximum) { continue; } // Add new node with current's value to front of the result else { ListNode* newNode = new ListNode(current->val); newNode->next = resultList; resultList = newNode; maximum = current->val; } } return resultList; }
};

