public: ListNode* swapNodes(ListNode* head, int k) { ListNode* dummyHead = new ListNode(0); dummyHead->next = head; ListNode* fast = dummyHead; ListNode* slow = dummyHead; for(int i = 0; i < k; i++){ fast = fast->next; } ListNode* temp = fast; while(fast != nullptr){ fast = fast->next; slow = slow->next; } swap(slow->val, temp->val); return dummyHead->next; }
};

