// 哈希解法
use std::collections::HashSet;
impl Solution { pub fn three_sum(nums: Vec<i32>) -> Vec<Vec<i32>> { let mut result: Vec<Vec<i32>> = Vec::new(); let mut nums = nums; nums.sort(); let len = nums.len(); for i in 0..len { if nums[i] > 0 { break; } if i > 0 && nums[i] == nums[i - 1] { continue; } let mut set = HashSet::new(); for j in (i + 1)..len { if j > i + 2 && nums[j] == nums[j - 1] && nums[j] == nums[j - 2] { continue; } let c = 0 - (nums[i] + nums[j]); if set.contains(&c) { result.push(vec![nums[i], nums[j], c]); set.remove(&c); } else { set.insert(nums[j]); } } } result }
} // 双指针法
use std::cmp::Ordering;
impl Solution { pub fn three_sum(nums: Vec<i32>) -> Vec<Vec<i32>> { let mut result: Vec<Vec<i32>> = Vec::new(); let mut nums = nums; nums.sort(); let len = nums.len(); for i in 0..len { if nums[i] > 0 { return result; } if i > 0 && nums[i] == nums[i - 1] { continue; } let (mut left, mut right) = (i + 1, len - 1); while left < right { match (nums[i] + nums[left] + nums[right]).cmp(&0){ Ordering::Equal =>{ result.push(vec![nums[i], nums[left], nums[right]]); left +=1; right -=1; while left < right && nums[left] == nums[left - 1]{ left += 1; } while left < right && nums[right] == nums[right+1]{ right -= 1; } } Ordering::Greater => right -= 1, Ordering::Less => left += 1, } } } result }
}

