Steps: Use a sliding window of size ( l ) to ( r ). Maintain the sum of elements in the current window. Check if the sum is greater than ( 0 ), and update the minimum sum if valid. Slide the window one element at a time, updating the sum in ( O(1) ). Complexity: Time Complexity : (O(n X (r - l + 1))) (for sliding windows of varying sizes). Space Complexity : (O(1)). Code: class Solution {
public: int minSumSubarray(vector<int>& nums, int l, int r) { int n = nums.size(); int minSum = INT_MAX; bool found = false; for (int k = l; k <= r; ++k) { int sum = 0; for (int i = 0; i < n; ++i) { sum += nums[i]; if (i >= k - 1) { if (sum > 0) { minSum = min(minSum, sum); found = true; } sum -= nums[i - k + 1]; } } } return found ? minSum : -1; }
};

