public: double findMaxAverage(vector<int>& nums, int k) { int left = 0; double result = -10000000.0; double sum = 0; for(int right = 0; right < nums.size(); right++){ sum += nums[right]; if(right - left + 1 == k){ double temp = sum / k; result = result > temp ? result : temp; sum -= nums[left]; left++; } } return result; }
};

